---@type IShop
local Shop = Plugins.Require("shop", "common.data.IShop")
---@class CShop : IShop
local CShop = class("CShop", Shop)

function CShop:updateShop(data)
    self.goods = data.goods or {}
    self.serverId = data.serverId or 0
    self.name = data.name or Lang:getString("gui.custom.shop.title")
    Events.ShopGoodsUpdateEvent:invoke(self.id)
    local entity = EntityCache:getEntityByServerId(self.serverId)
    if entity then
        entity.entity:setFlying(true)
        entity.entity:setHeadName(self.name)
    end
end

function CShop:checkEntityId(entityId)
    return EntityCache:getClientId(self.serverId) == entityId
end

return CShop